+  modalities: { input: ["text", "image"], output: ["text"] }, contextLimit: 1_000_000, outputLimit: 64_000,
+};
+
+function memoryRows(initial: SignedBlock[] = []): { readonly rows: AgentRows; readonly push: (...blocks: SignedBlock[]) => void } {
+  const blocks = [...initial];
+  return {
+    rows: { read: () => blocks },
+    push: (...added) => { blocks.push(...added); },
+  };
+}
+
+function eventQueue() {
+  const queue = Effect.runSync(Queue.unbounded<StepEvent, Error | Cause.Done>());
+  return {
+    events: queueIterable(queue),
+    push: (event: StepEvent) => { Queue.offerUnsafe(queue, event); },
+    fail: (error: Error) => { Queue.failCauseUnsafe(queue, Cause.fail(error)); },
+  };
+}
+
+function summary(events: readonly Anthropic.RawMessageStreamEvent[]): string[] {
+  return events.map((event) => {
+    if (event.type === "content_block_start") return `start:${event.index}:${event.content_block.type}`;
+    if (event.type === "content_block_delta") return `delta:${event.index}:${event.delta.type}`;
+    if (event.type === "content_block_stop") return `stop:${event.index}`;
+    return event.type;
+  });
