+function hasCause<T extends Error>(error: unknown, ctor: new (...args: never[]) => T): boolean {
+  let current: unknown = error;
+  while (current instanceof Error) {
+    if (current instanceof ctor) return true;
+    const failure = asRecord(current)?.["failure"];
+    if (failure instanceof Error && hasCause(failure, ctor)) return true;
+    current = current.cause;
+  }
+  return false;
+}
