diff --git a/src/util/createNestedOptions.ts b/src/util/createNestedOptions.ts
new file mode 100644
index 0000000..572aba7
--- /dev/null
+++ b/src/util/createNestedOptions.ts
@@ -0,0 +1,34 @@
+import type { NestedTestConfig } from '../types';
+
+export default function createNestedOptions({
+  key,
+  index,
+  parent,
+  parentPath,
+  originalParent,
+  options,
+}: NestedTestConfig) {
+  const k = key ?? index;
+  if (k == null) {
+    throw TypeError('Must include `key` or `index` for nested validations');
+  }
+
+  const isIndex = typeof k === 'number';
+  const value = parent[k];
+
+  return {
+    ...options,
+    parent,
+    value,
+    originalValue: originalParent[k],
+    // FIXME: tests depend on `index` being passed around deeply,
+    //   we should not let the options.key/index bleed through
+    key: undefined,
+    // index: undefined,
+    [isIndex ? 'index' : 'key']: k,
+    path:
+      isIndex || k.includes('.')
+        ? `${parentPath || ''}[${isIndex ? k : `"${k}"`}]`
+        : (parentPath ? `${parentPath}.` : '') + key,
+  };
+}
