+    const existing = this.rollupsByMetric.get(rollup.metric);
+    if (existing) existing.push(rollup);
+    else this.rollupsByMetric.set(rollup.metric, [rollup]);
+  }
+
+  read(metric: string): readonly Rollup[] {
+    return [...(this.rollupsByMetric.get(metric) ?? [])];
+  }
+}

