+import { TemplateError, type TemplateToken } from "./types.js";
+
+export type TemplateNode =
+  | { kind: "text"; value: string; position: number }
+  | { kind: "variable"; path: string; escaped: boolean; position: number }
+  | {
+      kind: "block";
+      block: "if" | "each";
+      path: string;
+      children: TemplateNode[];
+      position: number;
+    };
+
+interface OpenFrame {
+  block: "if" | "each";
+  path: string;
+  position: number;
+  children: TemplateNode[];
+}
+
+export function parse(tokens: readonly TemplateToken[]): TemplateNode[] {
+  const root: TemplateNode[] = [];
+  const stack: OpenFrame[] = [];
+
+  for (const token of tokens) {
+    const top = stack[stack.length - 1];
+    const target = top ? top.children : root;
+
+    switch (token.kind) {
+      case "text":
+      case "variable":
+        target.push(token);
+        break;
+      case "open":
+        stack.push({
+          block: token.block,
+          path: token.path,
+          position: token.position,
+          children: [],
+        });
+        break;
+      case "close": {
+        const frame = stack.pop();
+        if (!frame) {
+          throw new TemplateError(
+            `Unexpected closing tag {{/${token.block}}}`,
+            token.position,
+          );
+        }
+        if (frame.block !== token.block) {
+          throw new TemplateError(
+            `Mismatched closing tag {{/${token.block}}}; expected {{/${frame.block}}}`,
+            token.position,
+          );
+        }
+        const parent = stack[stack.length - 1];
+        (parent ? parent.children : root).push({
+          kind: "block",
+          block: frame.block,
+          path: frame.path,
+          children: frame.children,
+          position: frame.position,
+        });
+        break;
+      }
+    }
+  }
+
+  const unclosed = stack[stack.length - 1];
+  if (unclosed) {
+    throw new TemplateError(
+      `Unclosed {{#${unclosed.block}}} block`,
+      unclosed.position,
+    );
+  }
+
+  return root;
+}
