@@ -0,0 +1,76 @@
+import { TemplateError, type TemplateToken } from "./types.js";
+
+export type TemplateNode =
+  | { kind: "text"; value: string }
+  | { kind: "variable"; path: string; escaped: boolean }
+  | { kind: "if"; path: string; body: TemplateNode[] }
+  | { kind: "each"; path: string; body: TemplateNode[] };
+
+interface OpenBlockFrame {
+  block: "if" | "each";
+  path: string;
+  position: number;
+  body: TemplateNode[];
+}
+
+export function parse(tokens: readonly TemplateToken[]): TemplateNode[] {
+  const root: TemplateNode[] = [];
+  const stack: OpenBlockFrame[] = [];
+
+  const currentBody = (): TemplateNode[] =>
+    stack.length > 0 ? stack[stack.length - 1]!.body : root;
+
+  for (const token of tokens) {
+    switch (token.kind) {
+      case "text":
+        currentBody().push({ kind: "text", value: token.value });
+        break;
+      case "variable":
+        currentBody().push({
+          kind: "variable",
+          path: token.path,
+          escaped: token.escaped,
+        });
+        break;
+      case "open":
+        stack.push({
+          block: token.block,
+          path: token.path,
+          position: token.position,
+          body: [],
+        });
+        break;
+      case "close": {
+        const frame = stack.pop();
+        if (!frame) {
+          throw new TemplateError(
+            `Unexpected closing {{/${token.block}}} tag`,
+            token.position,
+          );
+        }
+        if (frame.block !== token.block) {
+          throw new TemplateError(
+            `Mismatched closing {{/${token.block}}} tag for {{#${frame.block}}}`,
+            token.position,
+          );
+        }
+        currentBody().push({
+          kind: frame.block,
+          path: frame.path,
+          body: frame.body,
+        });
+        break;
+      }
+    }
+  }
+
+  if (stack.length > 0) {
+    const unclosed = stack[stack.length - 1]!;
+    throw new TemplateError(
+      `Unclosed {{#${unclosed.block}}} tag`,
+      unclosed.position,
+    );
+  }
+
+  return root;
+}
