+        user: { name: "Ada", nil: null, undef: undefined },
+        a: null,
+      }),
+    ).toBe("Ada||||");
+  });
+
+  test("renders false and zero as strings", () => {
+    expect(render("flag={{flag}}, count={{count}}", { flag: false, count: 0 })).toBe(
+      "flag=false, count=0",
+    );
+  });
+
+  test("escapes &, <, >, double quote, and single quote without double escaping and leaves raw output unchanged", () => {
+    const input = `& < > " ' &amp;`;
+    expect(render("escaped={{text}} raw={{{text}}}", { text: input })).toBe(
+      "escaped=&amp; &lt; &gt; &quot; &#39; &amp;amp; raw=& < > \" ' &amp;",
+    );
+  });
+
+  test("renders if blocks using JavaScript truthiness and skips omitted bodies", () => {
+    const context = {
+      yes: true,
+      num: 1,
+      str: "ok",
+      no: false,
+      zero: 0,
+      empty: "",
+      nil: null,
+      get trap(): string {
+        throw new Error("should not evaluate omitted body");
+      },
+    };
+
+    expect(
+      render(
+        "{{#if yes}}Y{{/if}}{{#if num}}N{{/if}}{{#if str}}S{{/if}}" +
+          "{{#if no}}{{trap}}{{/if}}{{#if zero}}0{{/if}}{{#if empty}}E{{/if}}{{#if nil}}L{{/if}}",
+        context,
+      ),
+    ).toBe("YNS");
+  });
+
+  test("renders each blocks only for arrays and scopes the body to each item", () => {
+    expect(
+      render(
+        "{{#each empty}}x{{/each}}|{{#each absent}}x{{/each}}|{{#each obj}}x{{/each}}|{{#each str}}x{{/each}}|{{#each items}}[{{name}}]{{/each}}",
+        {
+          empty: [],
+          obj: { length: 2 },
+          str: "hi",
+          items: [{ name: "a" }, { name: "b" }],
+        },
+      ),
+    ).toBe("||||[a][b]");
+  });
+
+  test("supports arbitrary mixed and same-kind block nesting with item scope", () => {
+    const template =
+      "{{#if show}}" +
+      "{{#if nested}}" +
+      "{{#each groups}}" +
+      "{{title}}:" +
+      "{{#each items}}{{#if visible}}{{label}}{{/if}}{{/each}};" +
+      "{{/each}}" +
+      "{{/if}}" +
+      "{{/if}}";
+
+    expect(
+      render(template, {
+        show: true,
+        nested: true,
+        label: "outer-should-not-leak",
+        groups: [
+          {
+            title: "G1",
+            items: [
+              { visible: true, label: "A" },
+              { visible: false, label: "B" },
+              { visible: true, label: "C" },
+            ],
+          },
+          {
+            title: "G2",
+            items: [{ visible: true, label: "D" }],
+          },
+        ],
+      }),
+    ).toBe("G1:AC;G2:D;");
+  });
+
+  test("throws TemplateError with exact positions for structural errors in render()", () => {
+    const cases: Array<[string, number]> = [
+      ["ok {{/if}}", 3],
+      ["{{#if a}}{{#each b}}{{/if}}{{/each}}", 20],
+      ["prefix {{#if a}}body", 7],
+      ["hi {{unclosed", 3],
+    ];
+
+    for (const [tpl, expectedPos] of cases) {
+      try {
+        render(tpl, { a: true, b: [] });
+        expect.unreachable(`expected TemplateError for ${tpl}`);
+      } catch (error) {
+        expect(error).toBeInstanceOf(TemplateError);
+        const templateError = error as TemplateError;
+        expect(templateError.position).toBe(expectedPos);
+        expect(templateError.message).toStartWith("Template error: ");
