-    .join("");
+function escapeHtml(value: string): string {
+  return value
+    .replaceAll("&", "&amp;")
+    .replaceAll("<", "&lt;")
+    .replaceAll(">", "&gt;")
+    .replaceAll('"', "&quot;")
+    .replaceAll("'", "&#39;");
+}
+
+function resolvePath(context: unknown, path: string): unknown {
+  if (
+    path === "." ||
+    (path === "this" && (typeof context !== "object" || context === null))
+  ) {
+    return context;
+  }
+
+  let current: unknown = context;
+  for (const segment of path.split(".")) {
+    if (
+      typeof current !== "object" ||
+      current === null ||
+      !Object.hasOwn(current, segment)
+    ) {
+      return undefined;
+    }
+    current = (current as Record<string, unknown>)[segment];
+  }
+  return current;
+}
+
+function formatValue(value: unknown, escaped: boolean): string {
+  if (value === null || value === undefined) {
+    return "";
+  }
+  const text = String(value);
+  return escaped ? escapeHtml(text) : text;
+}
+
+function renderNodes(nodes: readonly TemplateNode[], context: unknown): string {
+  let output = "";
+  for (const node of nodes) {
+    switch (node.kind) {
+      case "text":
+        output += node.value;
+        break;
+      case "variable": {
+        const value = resolvePath(context, node.path);
+        output += formatValue(value, node.escaped);
+        break;
+      }
+      case "if":
+        if (Boolean(resolvePath(context, node.path))) {
+          output += renderNodes(node.body, context);
+        }
+        break;
+      case "each": {
+        const items = resolvePath(context, node.path);
+        if (Array.isArray(items)) {
+          for (const item of items) {
+            output += renderNodes(node.body, item);
+          }
+        }
+        break;
+      }
+    }
+  }
+  return output;
+}
+
+export function render(
+  template: string,
+  context: TemplateContext = {},
+): string {
+  const ast = parse(tokenize(template));
+  return renderNodes(ast, context);
 }
